import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.r0uj6mzT.js";const g=JSON.parse('{"title":"Upgrade notes","description":"","frontmatter":{},"headers":[],"relativePath":"operations/upgrading.md","filePath":"operations/upgrading.md","lastUpdated":1793490299000}'),n={name:"operations/upgrading.md"};function o(r,e,d,h,p,l){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="upgrade-notes" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h1><p>Most releases need nothing from you beyond upgrading the package. A release that does has a section here, newest first, saying what changed, what to do, and how to check it is done. Read every section between the version you run and the one you are installing. The GitHub release for such a version leads with the same notes, and the Arch and Ubuntu packages print a reminder when an upgrade crosses it.</p><p>Upgrade through the same package channel you installed, as described in <a href="/getting-started/installation#upgrade-or-remove">Installation</a>.</p><h2 id="v0-3-0" tabindex="-1">v0.3.0 <a class="header-anchor" href="#v0-3-0" aria-label="Permalink to &quot;v0.3.0&quot;">​</a></h2><p>This release changes how boomerangz stores recovery proofs and target bindings, and stops reading the old form: each source root now records the format of its state in <code>org.boomerangz:state:version</code>, and a root without the marker is in the earlier format. Until it is migrated, the daemon snapshots, prunes and replicates nothing for it, and reports <code>state on tank/data is format v1, and this build reads v2; stop the daemon and run boomerangz migrate tank/data</code>.</p><h3 id="migrate-every-source-root" tabindex="-1">Migrate every source root <a class="header-anchor" href="#migrate-every-source-root" aria-label="Permalink to &quot;Migrate every source root&quot;">​</a></h3><p>Stop the daemon before upgrading. After upgrading, preview the migration of every dataset that keeps boomerangz state:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p>Each root is listed with <code>Status: pending</code> and the properties it rewrites: every recovery proof, <code>org.boomerangz:state:reference:*</code>, shrinks to a fixed size; every target binding, <code>org.boomerangz:state:target:*</code>, keeps only the destination&#39;s identity and the dataset it maps to; and the version marker is written last. Holds, bookmarks and snapshots are not touched, so transfers continue incrementally afterwards. A root listed as <code>Status: blocked</code> names what cannot be carried over; resolve it, or forget that target with <code>boomerangz dataset clean --forget-target</code>, and preview again. Apply it, then start the daemon:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span></code></pre></div><p>A migration that is interrupted leaves the root in its old format and can be run again; it finishes what is left. Snapshots taken before the upgrade keep an <code>org.boomerangz:state:created</code> property, which this release no longer reads or writes; it goes with the snapshots as retention prunes them.</p><p>Check the result with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p>Every root now reads <code>Status: current</code>, and <code>boomerangz status</code> shows each target&#39;s next transfer verified.</p><h3 id="administrative-commands-print-text" tabindex="-1">Administrative commands print text <a class="header-anchor" href="#administrative-commands-print-text" aria-label="Permalink to &quot;Administrative commands print text&quot;">​</a></h3><p><code>dataset adopt</code>, <code>dataset clean</code>, <code>dataset reseed</code>, <code>dataset abort-receive</code>, <code>identity recover</code> and <code>migrate</code> now print a readable plan by default rather than JSON, matching <code>dataset list</code> and <code>dataset inspect</code>. A script that parses their output must add <code>--json</code>, which prints exactly the JSON these commands printed before:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>Check a script by running its command once by hand with <code>--json</code> and confirming the output is the JSON it expects; without the flag the output begins with <code>Dataset:</code> or <code>Current identity:</code> instead.</p><h2 id="v0-2-0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;v0.2.0&quot;">​</a></h2><p>This release replaces per-dataset actors with <a href="/guide/datasets">actor roots</a>. Stop the daemon before upgrading, and check the points below before starting it again.</p><h3 id="grant-rename-on-every-destination" tabindex="-1">Grant <code>rename</code> on every destination <a class="header-anchor" href="#grant-rename-on-every-destination" aria-label="Permalink to &quot;Grant `rename` on every destination&quot;">​</a></h3><p>Boomerangz now renames a placeholder dataset aside when a dataset gets a replica of its own where it had only held other replicas, so destinations need the <code>rename</code> permission in addition to what they had. Add it wherever you delegated permissions to the receiving account, for local destinations and on each remote:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup/boomerangz</span></span></code></pre></div><p>Use the account and dataset from your own <code>zfs allow</code> setup, as shown in <a href="/guide/security#destination-datasets">Security</a>, and check the result with <code>zfs allow backup/boomerangz</code>. Transfers that do not replace a placeholder keep working without it; one that does stops with a permission preflight error naming what is missing.</p><p>The daemon now also checks every destination for the permissions it may need, <code>rename</code> included, when it first reaches it, and reports anything missing as a warning in <code>boomerangz status</code> and in its log, naming the destination, the account and the permissions. After starting the upgraded daemon, run <code>boomerangz status</code> once a transfer has reached each destination; it lists no <code>WARNINGS</code> when every destination grants what it needs. A remote is checked only once its endpoint opens. After granting a missing permission, run <code>boomerangz config reload</code> to have the daemon check again. See <a href="/operations/#destination-permissions">Destination permissions</a>.</p><h3 id="review-how-your-datasets-are-grouped" tabindex="-1">Review how your datasets are grouped <a class="header-anchor" href="#review-how-your-datasets-are-grouped" aria-label="Permalink to &quot;Review how your datasets are grouped&quot;">​</a></h3><p>An enabled dataset with no enabled ancestor is now an actor root, and every enabled dataset beneath it is one of its members rather than a root of its own. Before starting the daemon, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>A dataset that used to replicate on its own and now reads <code>member</code> is snapshotted, pruned and sent by its root, on its own retention grid and with its own send options. <code>trigger</code>, <code>dataset adopt</code> and <code>dataset reseed</code> refuse a member and name its root; operate on the root instead. If a root&#39;s transfer then reports that an existing destination has no common base, reseed that root&#39;s target as described in <a href="/operations/recovery#reseed-a-target">Recovery</a>.</p><p>A dataset set to <code>enabled=off</code> beneath a root is excluded from it. A root with <code>replicate=on</code> still sends its whole subtree as one <code>zfs send -R</code> package.</p><h3 id="check-for-blocked-destinations" tabindex="-1">Check for blocked destinations <a class="header-anchor" href="#check-for-blocked-destinations" aria-label="Permalink to &quot;Check for blocked destinations&quot;">​</a></h3><p>When two roots&#39; replicas would overlap on a destination, that destination is now blocked for the roots involved, rather than replication failing at receive time. <code>dataset list</code> names blocked destinations beside each root, and <code>dataset inspect</code> says what each collides with. A root keeps snapshotting, pruning and sending to its other destinations. Fix the mapping - usually with <code>discard</code> or a different destination - and the block clears on the next scan.</p><h3 id="worth-knowing" tabindex="-1">Worth knowing <a class="header-anchor" href="#worth-knowing" aria-label="Permalink to &quot;Worth knowing&quot;">​</a></h3><ul><li><code>status</code> and the job log report a new state, <code>waiting-lock</code>, for a transfer held back by another job&#39;s lock on the same destination. Anything that matches job states should treat it as running.</li><li><code>dataset abort-receive</code> discards an interrupted receive that keeps failing to resume. See <a href="/operations/recovery#discard-an-interrupted-receive">Recovery</a>.</li><li>Turning <code>replicate=on</code> for a root that replicated member by member needs a reseed of its targets; turning it off again does not.</li></ul>',34)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
